command:
// Cue reminder — run once at the start of a session.
//
// From then on, every scene change whispers you that scene's ambience cue and
// the command to paste into your music bot. The cue is compiled onto the scene
// from its vault note by compile-game.mjs; nothing here streams audio, and
// nothing here is a Foundry playlist (see docs/CONTENT_AUTHORING.md,
// "Ambience stays out of Foundry").
//
// Safe to run twice — the second run just tells you it is already armed.
const SCOPE = "foundry-cue";

// The cue is authored in your own vault, but it lands in chat HTML, so escape
// it rather than trusting that no note ever contains an angle bracket.
const esc = s =>
  String(s).replace(
    /[&<>"']/g,
    c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );

const show = scene => {
  const audio = scene?.flags?.[SCOPE]?.audio;
  if (!audio) return;
  const rows = [];
  if (audio.cue) rows.push(`<p><em>${esc(audio.cue)}</em></p>`);
  const paste = audio.command ?? audio.ref;
  if (paste) rows.push(`<p><code>${esc(paste)}</code></p>`);
  if (!rows.length) return;
  ChatMessage.create({
    content: `<strong>&#9834; ${esc(scene.name)}</strong>${rows.join("")}`,
    whisper: [game.user.id],
  });
};

if (globalThis.__foundryCueArmed) {
  ui.notifications.info("Cue reminder is already armed for this session.");
} else {
  Hooks.on("canvasReady", () => show(canvas.scene));
  globalThis.__foundryCueArmed = true;
  ui.notifications.info("Cue reminder armed — each scene change will whisper its cue.");
  show(canvas.scene); // Do not wait for the next scene to say something useful.
}
